import { createBe } from '../be.js';
// Définition des presets avec des types constants
const examplePresets = {
    display: ['flex', 'grid', 'string'],
    position: ['absolute', 'fixed', 'static', 'relative'],
    margin: ['top', 'bottom', 'left', 'right']
};
export class DynamicHandler {
    beElement;
    attr;
    constructor(element, attr = 'style') {
        this.beElement = element;
        this.attr = attr;
    }
    handler = {
        get: (target, prop) => {
            if (prop in target) {
                return Reflect.get(target, prop);
            }
            const matchSet = prop.match(/^set([A-Z]\w*)([A-Z]\w*)?$/);
            if (matchSet) {
                const [, mainProp, subProp] = matchSet;
                const cssProp = mainProp.toLowerCase();
                if (subProp) {
                    const cssValue = subProp.toLowerCase();
                    return () => {
                        this.beElement.eachNode((el) => {
                            el[this.attr][cssProp] = cssValue;
                        });
                    };
                }
                else {
                    return (value) => {
                        this.beElement.eachNode((el) => {
                            if (value === undefined) {
                                el[this.attr][cssProp] = '';
                            }
                            else {
                                el[this.attr][cssProp] = value;
                            }
                        });
                    };
                }
            }
            return undefined;
        }
    };
    proxy() {
        return new Proxy(this, this.handler);
    }
}
